import java.util.List;
import java.util.Random;

/**
 * A class representing shared characteristics of plants.
 *
 * @version 2022.03.01
 */
public abstract class Plants extends Actor
{
    //private static final Random rand = Randomizer.getRandom();
    private int sunLevel; 
    private int waterLevel;
    /**
     * Create a new plant at location in field.
     *
     * @param field The field currently occupied.
     * @param location The location within the field.
     */
    public Plants(Field field, Location location)
    {
        super(field,location);
        sunLevel = getRandom().nextInt(10) + 1;
        waterLevel = getRandom().nextInt(10) + 1;
    }


    /**
     * Generate a number representing how much a plant grows,if it can grow.
     * @return The number of squares it grows into(may be zero).
     */
    protected int growth(int step)
    {
        int births = 0;
        if(getAge() >= getBreedingAge() && getAge() % 2 == 0 ) {
            births = getRandom().nextInt(getMaxLitter()) + 1;
        }

        if(step > 1600){
            births = births + 20;
        }
        return births;
    }

    /**
     * Get growing age of a plant.
     * @return Growing age of the plant.
     */
    abstract protected int getBreedingAge();

    /**
     * Get the maximum number of squares the plant can grow into.
     * @return  The number of squares the plant can grow into.
     */
    abstract protected int getMaxLitter();  

    /**
     * Increase the current water level.
     */
    protected void increaseWaterLevel(){
        waterLevel++;
    }

    /**
     * Decrease the current water level.
     */
    protected void decreaseWaterLevel(){
        waterLevel--;
    }

    /**
     * Increase the current sun level.
     */
    protected void increaseSunLevel(){
        sunLevel++;
    }

    /**
     * Decrease the current sun level.
     */
    protected void decreaseSunLevel(){
        sunLevel--;
    }

    /**
     * Get the current water level.
     * @return The plants current water level.
     */
    protected int getWaterLevel(){
        return waterLevel;
    }

    /**
     * Get the current sun level.
     * @return The plants current sun level.
     */
    protected int getSunLevel(){
        return sunLevel;
    }

    /**
     * If either the water level or the sun level is 0 the plant dies.
     * @param step. The number of steps in the simulation.
     */
    protected void incrementAge(int step){
        super.incrementAge(step);
        if(waterLevel == 0 || sunLevel == 0){
            setDead();
        }
    }
}

import java.util.List;
import java.util.Iterator;
import java.util.Map;

/**
 * A class representing shared characteristics of animals.
 *
 * @version 2022.03.01
 */
public abstract class Animal extends Actor
{
    private double foodLevel;
    private boolean isGirl;
    private boolean isHealthy;
    //the number of steps an animal takes when infected.
    private int infectedStepCounter;
    //how many steps animal needs to wait before it can breed again.
    private int timeLeftUntilBreedingAgain = 0;
    /**
     * Create a new animal at location in field.
     * 
     * @param field The field currently occupied.
     * @param location The location within the field.
     */
    public Animal(Field field, Location location)
    {
        super(field,location);
        setRandomGender();
        isHealthy = true;
        infectedStepCounter = 0;
        timeLeftUntilBreedingAgain= getRandom().nextInt(getMaxTimeUntilBreedingAgain());
        if(!isGirl){
        timeLeftUntilBreedingAgain = 0;
        }
    }

    /**
     * Make this animal act - that is: make it do
     * whatever it wants/needs to do during the current step.
     * @param newAnimals A list to receive newly born animals.
     * @param simulator The simulator.
     */
    public void act(List<Actor> newAnimals, Simulator simulator){
        setGrowthLevel(getGrowthPerStep());
        if(simulator.isDay()){
            actDuringDay(newAnimals, simulator);
        }else{
            actDuringNight(newAnimals, simulator);
        }
    }

    /**
     * Execute the default daytime behavior for animals.
     * @param newAnimals A list to receive newly born animals.
     * @param simulator The simulator.
     */
    protected void actDuringDay(List<Actor> newAnimals, Simulator simulator)
    {
        incrementAge(simulator.getSteps());
        incrementHunger();
        if(isActive()) {
            giveBirth(newAnimals);
            move(simulator);
        }
    }

    /**
     * Execute nighttime behavior for animals.
     * Subclasses can override this if they gain night actions later.
     * @param newAnimals A list to receive newly born animals.
     * @param simulator The simulator.
     */
    protected void actDuringNight(List<Actor> newAnimals, Simulator simulator)
    {
    }

    /**
     * Move the animal according to the current weather and nearby food.
     * @param simulator The simulator.
     */
    private void move(Simulator simulator)
    {
        Location newLocation = null;
        newLocation = findFood(getFindingFoodProbability(simulator.getWeather()));
        if(newLocation == null) { 
            // No food found - try to move to a free location.
            newLocation = getField().freeAdjacentLocation(getLocation());
        }
        if(newLocation != null) {
            setLocation(newLocation);
        }
        else {
            // Overcrowding.
            setDead();
        }
    }

    /**
     * Returns how much this animal grows each step.
     * @return The per-step growth increment.
     */
    abstract protected double getGrowthPerStep();

    /**
     * An animal can breed if it has reached the breeding age.
     * @return true if an animal is able to breed
     */
    protected boolean canBreed()
    {
        return getAge() >= getBreedingAge();
    }

    /**
     * Get breeding age of an animal.
     * @return int. Breeding age of the animal;
     */
    abstract protected int getBreedingAge();

    /**
     * Check whether or not this animal is to give birth at this step.
     * New births will be made into free adjacent locations.
     * @param newAnimals A list to return newly born animals.
     */
    protected void giveBirth(List<Actor> newAnimals)
    {
        // New animals are born into adjacent locations.
        // Get a list of adjacent free locations.
        Field field = getField();
        List<Location> free = field.getFreeAdjacentLocations(getLocation());
        if (timeLeftUntilBreedingAgain != 0){
            timeLeftUntilBreedingAgain --;
        }
        int births = breed();
        for(int b = 0; b < births && free.size() > 0; b++) {
            Location loc = free.remove(0);
            Animal baby = createYoung(field, loc);
            if(!getHealth()){
                baby.setUnhealthy(); //setting the baby to be unhealthy if the parent is unhealthy.
            }
            newAnimals.add(baby);
        }
    }

    /**
     * Generate a number representing the number of births,
     * if it can breed.
     * Females can mate with a male even  regardless of the males breeding time .
     * @return The number of births (may be zero).
     */
    protected int breed()
    {
        int births = 0;
        if(canBreed()  && findMate() && getRandom().nextDouble() <= getBreedingProbability() && timeLeftUntilBreedingAgain == 0) {
            births = getRandom().nextInt(getMaxLitterSize()) + 1;
            timeLeftUntilBreedingAgain = getMaxTimeUntilBreedingAgain();
        }
        return births;
    }

    /**
     * If the animal can find a mate of the opposite gender that can breed, true is returned.
     * @return true if the animal can find a mate.
     */
    protected boolean findMate()
    {
        Field field = getField();
        List<Location> adjacent = field.adjacentLocations(getLocation());
        Iterator<Location> it = adjacent.iterator();
        while(it.hasNext()) {
            Location where = it.next();
            Actor animal = field.getObjectAt(where);
            if (animal != null && animal.getClass() == getClass()){
                Animal mate = (Animal) animal;
                if(isActive() && getIsGirl() && !mate.getIsGirl() && mate.canBreed()){
                    if(!getHealth() || !mate.getHealth()){
                        setUnhealthy();
                        mate.setUnhealthy();
                    }
                    return true;
                }
            }
        }
        return false;
    }

    /**
     * Returns the breeding probability of the animal
     * @return breeding probability of the animal.
     */
    abstract protected double getBreedingProbability();

    /**
     * Returns the maximum number of babies the animal can give birth to at once.
     * @return max litter size of the animal.
     */
    abstract protected int getMaxLitterSize();

    /**
     * Create a newborn instance of this animal's species.
     * @param field The field the newborn is in.
     * @param location The newborn's location.
     * @return A newborn animal of the same species.
     */
    abstract protected Animal createYoung(Field field, Location location);

    /**
     * Returns the animal's current food level.
     * @return the animal's food level.
     */
    protected double getFoodLevel(){
        return foodLevel;
    }

    /**
     * Sets the animal's food level.
     * @param food level The amount of food the animal gets.
     */
    protected void setFoodLevel(double foodlevel){
        this.foodLevel += foodlevel ; 
    }

    /**
     * Make this animal more hungry. This could result in the animal's death.
     */
    protected void incrementHunger()
    {
        foodLevel--;
        if(foodLevel <= 0) {
            setDead();
        }
    }

    /**
     * Look for preys adjacent to the current location.
     * Only the first live prey is eaten.
     * @param probability The probability the animal finds prey.
     * @return Where food was found, or null if it wasn't.
     */
    protected Location findFood(double probability)
    {

        Field field = getField();
        List<Location> adjacent = field.adjacentLocations(getLocation());
        Iterator<Location> it = adjacent.iterator();

        if(getRandom().nextDouble() < probability && getFoodLevel() < getMaxFoodLevel()){
            while(it.hasNext()) {
                Location where = it.next();
                Actor currentAnimal = field.getObjectAt(where);
                if(currentAnimal != null){
                    Integer foodValue = getFoodValues().get(currentAnimal.getClass());
                    if(foodValue != null){
                        if (currentAnimal instanceof Animal){
                            Animal current = (Animal)currentAnimal;
                            if(!current.getHealth()){
                                setUnhealthy();
                            }
                        }
                        currentAnimal.setDead();

