    /**
     * Provide a graphical view of a rectangular field. This is 
     * a nested class (a class defined inside a class) which
     * defines a custom component for the user interface. This
     * component displays the field.
     * This is rather advanced GUI stuff - you can ignore this 
     * for your project if you like.
     */
    private class FieldView extends JPanel
    {
        private final int GRID_VIEW_SCALING_FACTOR = 6;

        private int gridWidth, gridHeight;
        private int xScale, yScale;
        Dimension size;
        private Graphics g;
        private Image fieldImage;

        /**
         * Create a new FieldView component.
         */
        public FieldView(int height, int width)
        {
            gridHeight = height;
            gridWidth = width;
            size = new Dimension(0, 0);
        }

        /**
         * Tell the GUI manager how big we would like to be.
         */
        public Dimension getPreferredSize()
        {
            return new Dimension(gridWidth * GRID_VIEW_SCALING_FACTOR,
                gridHeight * GRID_VIEW_SCALING_FACTOR);
        }

        /**
         * Prepare for a new round of painting. Since the component
         * may be resized, compute the scaling factor again.
         */
        public void preparePaint()
        {
            if(! size.equals(getSize())) {  // if the size has changed...
                size = getSize();
                fieldImage = fieldView.createImage(size.width, size.height);
                g = fieldImage.getGraphics();

                xScale = size.width / gridWidth;
                if(xScale < 1) {
                    xScale = GRID_VIEW_SCALING_FACTOR;
                }
                yScale = size.height / gridHeight;
                if(yScale < 1) {
                    yScale = GRID_VIEW_SCALING_FACTOR;
                }
            }
        }

        /**
         * Paint on grid location on this field in a given color.
         */
        public void drawMark(int x, int y, Color color)
        {
            g.setColor(color);
            g.fillRect(x * xScale, y * yScale, xScale-1, yScale-1);
        }

        /**
         * The field view component needs to be redisplayed. Copy the
         * internal image to screen.
         */
        public void paintComponent(Graphics g)
        {
            if(fieldImage != null) {
                Dimension currentSize = getSize();
                if(size.equals(currentSize)) {
                    g.drawImage(fieldImage, 0, 0, null);
                }
                else {
                    // Rescale the previous image.
                    g.drawImage(fieldImage, 0, 0, currentSize.width, currentSize.height, null);
                }
            }
        }
    }
}

import java.util.Random;

/**
 * Sets the time based on the number of steps in the simulator.
 *
 * @version 2022.03.01
 */
public class Timer
{
    private String currentTime;
    private String minutes;
    private static final Random random = Randomizer.getRandom();

    /**
     * Constructor for objects of class Timer
     */
    public Timer()
    {

    }

    /**
     * Generates a random time between 6 and 11am.
     */
    public String getMorningTime(){
        currentTime = Integer.toString(random.nextInt(6) + 6);
        return currentTime;
    }

    /**
     * Generates a random time between 12 and 5pm.
     */
    public String getAfternoonTime(){
        currentTime = Integer.toString(random.nextInt(6) + 12);
        return currentTime;
    }

    /**
     * Generates a random time between 6 and 11pm.
     */
    public String getEveningTime(){
        currentTime = Integer.toString(random.nextInt(6) + 18);
        return currentTime;
    }

    /**
     * Generates a random time between 12 and 5am.
     */
    public String getNightTime(){
        currentTime =Integer.toString(random.nextInt(6));
        return currentTime;
    }

    /**
     * Adds ":" to the current time string + minutes
     * @return the current time string with ':' + minutes.
     */
    public String toString(){
        return currentTime +":" + minutes;
    }

    /**
     * Randomly generates minutes.
     * @return minutes as a string.
     */
    public String getMinutes(){
        int min = random.nextInt(60);
        minutes = Integer.toString(min);
        if(min < 10){
            minutes = "0" + minutes;
        }
        return minutes;
    }

    /**
     * Uses the step number to decide what time of day it is to randomly generate an apporopriate time.
     * @param steps. The step number currently in the simulation.
     * @return Current time in the simualtion.
     */
    public String getTime(int steps){
        int value = steps % 4;
        if(value == 0){
            currentTime =  getMorningTime();
        } else if(value == 1){
            currentTime = getAfternoonTime();
        } else if(value == 2){
            currentTime = getEveningTime();
        } else if(value == 3){
            currentTime = getNightTime();
        }
        getMinutes();
        return toString();
    }
}

import java.awt.*;
import java.awt.event.*;
import javax.swing.*;
import java.util.LinkedHashMap;
import java.util.Map;

/**
 * A graphical view of the simulation grid.
 * The view displays a colored rectangle for each location 
 * representing its contents. It uses a default background color.
 * Colors for each type of species can be defined using the
 * setColor method.
 *
 * @version 2022.03.01
 */
public class SimulatorView extends JFrame
{
    // Colors used for empty locations.
    private static final Color EMPTY_COLOR = Color.white;

    // Color used for objects that have no defined color.
    private static final Color UNKNOWN_COLOR = Color.gray;

    private final String STEP_PREFIX = "Step: ";
    private final String POPULATION_PREFIX = "Population: ";
    private final String DAY_PREFIX = "Number of Days: ";
    private final String INFECTION_PREFIX = "Number of animals infected: ";

    private JLabel stepLabel, population, infoLabel, dayLabel;

    private JButton stepButton, resetButton, infectionButton;

    private FieldView fieldView;
    // A map for storing colors for participants in the simulation
    private Map<Class, Color> colors;
    // A statistics object computing and storing simulation information
    private FieldStats stats;

    private int infectedPopulationCount;
    private Simulator simulator;
    private Timer timer;
    /**
     * Create a view of the given width and height.
     * @param height The simulation's height.
     * @param width  The simulation's width.
     */
    public SimulatorView(int height, int width,  Simulator simulator)
    {
        this.simulator =simulator;
        timer = new Timer();
        stats = new FieldStats();
        colors = new LinkedHashMap<>();

        setTitle("Safari Predator-Prey Simulation");

        createLabels();
        createButtons();
        JPanel toolBar = new JPanel();

        toolBar.add(stepButton);
        toolBar.add(resetButton);
        toolBar.add(infectionButton);
        toolBar.add(population);

        setLocation(100, 50);

        fieldView = new FieldView(height, width);

        Container contents = getContentPane();

        JPanel infoPane = new JPanel(new BorderLayout());
        infoPane.add(stepLabel, BorderLayout.WEST);
        infoPane.add(infoLabel, BorderLayout.CENTER);
        infoPane.add(dayLabel, BorderLayout.EAST);
        contents.add(infoPane, BorderLayout.NORTH);
        contents.add(fieldView, BorderLayout.CENTER);
        contents.add(toolBar, BorderLayout.SOUTH);

        pack();
        setVisible(true);
    }

    /**
     * Called when the 'One Step Button' button is clicked.
     */
    private void nextButton(){
        simulator.simulateOneStep();
    }

    /**
     * Called when the 'Introduce Infection Button' button is clicked.
     */
    private void infectionButton(){
        simulator.introduceInfection();
    }

    /**
     * Called when the 'Reset Button' button is clicked.
     */
    private void resetButton(){
        simulator.reset();
    }

    /**
     * Define a color to be used for a given class of actor.
     * @param actorClass The actor's Class object.
     * @param color The color to be used for the given class.
     */
    public void setColor(Class actorClass, Color color)
    {
        colors.put(actorClass, color);
    }

    /**
     * Display a short information label at the top of the window.
     */
    public void setInfoText(String text)
    {
        infoLabel.setText(text);
    }

    /**
     * Create the reset, one step and infection buttons.
     * Adds an action to each button.
     */
    private void createButtons(){
        stepButton  = new JButton("One Step ");
        resetButton  = new JButton("Reset");
        infectionButton  = new JButton("Introduce Infection");
        stepButton.addActionListener(new ActionListener() {
                public void actionPerformed(ActionEvent e) { nextButton(); }
            });
        infectionButton.addActionListener(new ActionListener() {
                public void actionPerformed(ActionEvent e) { infectionButton(); }
            });
        resetButton.addActionListener(new ActionListener() {
                public void actionPerformed(ActionEvent e) { resetButton(); }
            });
    }

    /**
     * Create the different labels to display on the simulation.
     */
    private void createLabels(){
        stepLabel = new JLabel(STEP_PREFIX, JLabel.CENTER);
        infoLabel = new JLabel("  ", JLabel.CENTER);
        population = new JLabel(POPULATION_PREFIX, JLabel.CENTER);
        dayLabel = new JLabel(" ", JLabel.CENTER);
    }

    /**
     * @return The color to be used for a given class of actor.
     */
    private Color getColor(Class animalClass)
    {
        Color col = colors.get(animalClass);
        if(col == null) {
            // no color defined for this class
            return UNKNOWN_COLOR;
        }
        else {
            return col;
        }
    }

    /**
     * Show the current status of the field.
     * @param step Which iteration step it is.
     * @param field The field whose status is to be displayed.
     */
    public void showStatus(Field field)
    {
        if(!isVisible()) {
            setVisible(true);
        }

        stepLabel.setText(STEP_PREFIX + simulator.getSteps() );
        stats.reset();
        infectedPopulationCount = 0;

        fieldView.preparePaint();

        for(int row = 0; row < field.getDepth(); row++) {
            for(int col = 0; col < field.getWidth(); col++) {
                Actor actor = field.getObjectAt(row, col);
                if(actor != null) {
                    stats.incrementCount(actor, simulator);
                    fieldView.drawMark(col, row, getColor(actor.getClass()));
                    if(actor instanceof Animal){
                        Animal animal = (Animal) actor;
                        if (!animal.getHealth()){
                            infectedPopulationCount ++;
                        }
                    }
                }
                else {
                    fieldView.drawMark(col, row, EMPTY_COLOR);
                }
            }
        }
        stats.countFinished();
        if(simulator.isDay()){
            dayLabel.setText( DAY_PREFIX+ simulator.getNoOfDays() + "      Time: " + timer.getTime(simulator.getSteps()) + "   It is Day Time. ");
        }else{
            dayLabel.setText( DAY_PREFIX+ simulator.getNoOfDays() + "      Time: " + timer.getTime(simulator.getSteps()) + "   It is Night Time ");
        }

        infoLabel.setText(" " + simulator.getWeather() + "        " + INFECTION_PREFIX + infectedPopulationCount );
        population.setText(POPULATION_PREFIX + stats.getPopulationDetails(field, simulator));
        fieldView.repaint();
    }

    /**
     * Determine whether the simulation should continue to run.
     * @return true If there is more than one species alive.
     */
    public boolean isViable(Field field)
    {
        return stats.isViable(field, simulator);
    }

